INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Läuft PHP immer nur auf dem Server?', 2, '[{"text": "Ja", "correct": true, "because": "PHP ist serverseitig"}, {"text": "Nein", "correct": false, "because": "Nicht clientseitig wie JavaScript"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel von PHP in der Webentwicklung?', 3, '[{"text": "Dynamische Inhalte erzeugen", "correct": true, "because": "Generiert HTML serverseitig"}, {"text": "Clientseitige Animationen", "correct": false, "because": "Aufgabe von JavaScript"}, {"text": "Manuelle Serverwartung", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben kann PHP übernehmen?', 5, '[{"text": "Datenbankzugriff", "correct": true, "because": "Verbindet mit MySQL"}, {"text": "Formularverarbeitung", "correct": true, "because": "Verarbeitet Benutzereingaben"}, {"text": "3D-Rendering", "correct": false, "because": "Nicht PHP-typisch"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Andere Domäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PHP unterstützt objektorientierte Programmierung. b) Es ist ausschließlich clientseitig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist serverseitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Entwicklung mit PHP?', 4, '[{"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Schützen vor Angriffen"}, {"text": "Datenbankverbindung", "correct": false, "because": "Häufig benötigt"}, {"text": "Farbschema der IDE", "correct": true, "because": "Irrelevant für Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PHP für statische Webseiten geeignet ist?', 2, '[{"text": "Nein", "correct": true, "because": "Ideal für dynamische Inhalte"}, {"text": "Ja", "correct": false, "because": "Statisch weniger effizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für PHP-Sicherheit entscheidend?', 3, '[{"text": "Input-Validierung", "correct": true, "because": "Schützt vor SQL-Injection"}, {"text": "Hohe Bildauflösung", "correct": false, "because": "Nicht relevant"}, {"text": "Manuelle Codeeingabe", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologien arbeiten oft mit PHP zusammen?', 5, '[{"text": "MySQL", "correct": true, "because": "Für Datenbankzugriff"}, {"text": "Apache", "correct": true, "because": "Webserver für PHP"}, {"text": "DirectX", "correct": false, "because": "Für Spieleentwicklung"}, {"text": "Routerkonfiguration", "correct": false, "because": "Netzwerkdomäne"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) PHP ist für CMS wie WordPress geeignet. b) Es ist nur für kleine Projekte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist nicht beschränkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für PHP-Entwicklung?', 4, '[{"text": "Webserver", "correct": false, "because": "Verarbeitet PHP-Skripte"}, {"text": "PHP-Interpreter", "correct": false, "because": "Führt Code aus"}, {"text": "3D-Modellierungssoftware", "correct": true, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist PHP nur für Webseiten gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für CLI-Skripte nutzbar"}, {"text": "Ja", "correct": false, "because": "Vielseitiger Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsprobleme gibt es bei PHP?', 4, '[{"text": "SQL-Injection", "correct": true, "because": "Ohne Validierung anfällig"}, {"text": "Cross-Site-Scripting", "correct": true, "because": "Bei unsicherer Ausgabe"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Netzwerkproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass PHP immer langsam ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Optimierung verbessert Leistung"}, {"text": "Ja", "correct": false, "because": "Leistung abhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der PHP-Programmierung?', 3, '[{"text": "Sichere Eingabeverarbeitung", "correct": true, "because": "Schützt vor Angriffen"}, {"text": "Maximale Codezeilen", "correct": false, "because": "Klarheit wichtiger"}, {"text": "Manuelle Tests", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) PHP unterstützt Frameworks wie Laravel. b) Es benötigt immer eine GUI.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist serverseitig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet PHP?', 5, '[{"text": "Einfache Integration", "correct": true, "because": "Mit HTML kombinierbar"}, {"text": "Breite Unterstützung", "correct": true, "because": "Viele Server nutzen PHP"}, {"text": "Clientseitige Logik", "correct": false, "because": "Serverseitig"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher einfach"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei PHP-Entwicklung unwichtig?', 3, '[{"text": "Sicherheit", "correct": false, "because": "Schützt Anwendung"}, {"text": "Datenbankzugriff", "correct": false, "because": "Häufig benötigt"}, {"text": "Musikwiedergabe", "correct": true, "because": "Kein PHP-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob PHP für große Projekte geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Z. B. Facebook nutzt PHP"}, {"text": "Nein", "correct": false, "because": "Skalierbar mit Frameworks"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist PHP eine kompilierte Sprache?', 3, '[{"text": "Nein", "correct": true, "because": "Interpretierte Skriptsprache"}, {"text": "Ja", "correct": false, "because": "Wird zur Laufzeit verarbeitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu PHP?', 4, '[{"text": "Entwicklung eines CMS", "correct": true, "because": "WordPress nutzt PHP"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Andere Domäne"}, {"text": "3D-Animation", "correct": false, "because": "Spezialisierte Software"}]');
